'use client'

import { useId, useLayoutEffect, useRef, useState, type ComponentProps, type MouseEvent, type ReactNode, type RefObject } from 'react'
import { Dialog } from '@base-ui/react/dialog'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import { AppContent } from '../../patterns/application-ui/AppContent'
import { ShellContext, TopBar } from '../../patterns/application-ui/TopBar'
import styles from './AppShell.module.css'

export type AppShellLayout = 'sidebar' | 'top-bar'
export type AppShellSurface = 'solid' | 'transparent'

/** `null`, `false` and `undefined` render nothing, so they are no navigation either. */
const given = (node: ReactNode) => node != null && node !== false

export interface AppShellProps extends ComponentProps<'div'> {
  /**
   * `sidebar`: the sidebar runs the full height and there is no top bar on
   * wide screens, so search and the account go in the NavSidebar's header
   * and footer. `top-bar`: the header runs the full width above the sidebar and
   * the content.
   */
  layout?: AppShellLayout
  /** The header: `solid` on the card colour, or `transparent` on the canvas. */
  topBarSurface?: AppShellSurface
  /** The sidebar: `solid` on the card colour, or `transparent` on the canvas. */
  sidebarSurface?: AppShellSurface
  /** The logo. The shell places it, in the same spot in either layout. */
  brand?: ReactNode
  /** A NavSidebar. Beside the page from 64rem; in the drawer below that. */
  sidebar?: ReactNode
  /**
   * A TopBar. Above the page in `top-bar`; in `sidebar` only while the
   * sidebar is in the drawer, for the menu button.
   */
  header?: ReactNode
  /**
   * What the drawer holds on narrow screens. Defaults to `sidebar`; pass it
   * for a top-navigation shell, whose links move into the drawer below 48rem.
   */
  mobileNavigation?: ReactNode
  /** Names the drawer and its button. */
  navigationLabel?: string
  /** The `id` of the `main` element, which the skip link targets. Generated if not given. */
  mainId?: string
  children: ReactNode
}

/**
 * The frame of an application, a template. It only places three patterns,
 * the TopBar, the NavSidebar and the AppContent, on the Theme's canvas, with no padding or gap of its
 * own; the Theme's `contentStyle` decides whether the page is one flat
 * surface or blocks on the canvas. The sidebar stays put while the content
 * scrolls; on narrow screens the navigation moves into a drawer that the
 * header's menu button opens.
 */
export function AppShell({
  layout = 'sidebar',
  topBarSurface = 'solid',
  sidebarSurface = 'transparent',
  brand,
  sidebar,
  header,
  mobileNavigation,
  navigationLabel = 'Navigation',
  mainId,
  children,
  className,
  ...props
}: AppShellProps) {
  const [open, setOpen] = useState(false)
  const autoId = useId()
  const mainRef = useRef<HTMLElement>(null)
  const id = mainId ?? `${autoId}main`
  const hasSidebar = given(sidebar)
  const hasMobileNavigation = given(mobileNavigation)
  const drawerContent = hasMobileNavigation ? mobileNavigation : hasSidebar ? sidebar : null
  const hasDrawer = drawerContent !== null
  const hasBrand = given(brand)
  // The logo is rendered once, in the place it shows: in the sidebar for the
  // sidebar layout while the sidebar is beside the page, else in the header.
  // CSS alone would need two copies, and a logo can hold an id or a menu.
  const frameRef = useRef<HTMLDivElement>(null)
  const isWide = useIsWide(frameRef)
  const brandInSidebar = hasBrand && layout === 'sidebar' && hasSidebar && isWide
  // The sidebar layout still needs a bar for the menu button while the sidebar is in the drawer.
  const top = given(header) ? header : hasDrawer || hasBrand ? <TopBar /> : null
  // A link chosen in the drawer navigates; the drawer should not stay over the new page.
  const closeOnLink = (e: MouseEvent) => {
    if ((e.target as HTMLElement).closest('a[href]')) setOpen(false)
  }
  return (
    <ShellContext.Provider
      value={{
        hasDrawer,
        drawerHolds: hasSidebar ? 'sidebar' : 'links',
        isOpen: open,
        open: () => setOpen(true),
        label: navigationLabel,
        brand: brandInSidebar ? null : brand,
        brandCell: layout === 'top-bar' && hasSidebar,
      }}
    >
      <div
        className={cn(
          styles.shell,
          layout === 'top-bar' ? styles.topBarLayout : styles.sidebarLayout,
          hasSidebar && styles.withSidebar,
          hasMobileNavigation && styles.withMobileNavigation,
          hasBrand && styles.withBrand,
          className,
        )}
        {...props}
      >
        {/* Focus is moved by hand: the browser's own jump would also scroll
            the window, and a generated id is not a tidy URL fragment. */}
        <a
          href={`#${id}`}
          className={styles.skip}
          onClick={(e) => {
            e.preventDefault()
            mainRef.current?.focus()
          }}
        >
          Skip to content
        </a>
        {/* The shell is the size container and the frame its grid, so the
            layout follows the shell's own width: an element cannot query itself. */}
        <div ref={frameRef} className={styles.frame}>
          {top && (
            <div className={styles.top} data-surface={topBarSurface}>
              {top}
            </div>
          )}
          {hasSidebar && (
            <div className={styles.sidebar} data-surface={sidebarSurface}>
              {brandInSidebar && <div className={styles.sidebarBrand}>{brand}</div>}
              {sidebar}
            </div>
          )}
          <AppContent ref={mainRef} id={id}>
            {children}
          </AppContent>
        </div>
      </div>
      {hasDrawer && (
        <Dialog.Root open={open} onOpenChange={setOpen}>
          <Dialog.Portal>
            <Dialog.Backdrop className={styles.backdrop} />
            <Dialog.Popup className={styles.drawer} onClick={closeOnLink}>
              <Dialog.Title className={styles.srOnly}>{navigationLabel}</Dialog.Title>
              <Dialog.Close className={styles.drawerClose} aria-label={`Close ${navigationLabel.toLowerCase()}`}>
                <Icon name="close" />
              </Dialog.Close>
              {drawerContent}
            </Dialog.Popup>
          </Dialog.Portal>
        </Dialog.Root>
      )}
    </ShellContext.Provider>
  )
}

/** Whether the element is at least 64rem wide, the width where the sidebar sits beside the page (the CSS container query's twin). */
function useIsWide(ref: RefObject<HTMLElement | null>) {
  const [isWide, setIsWide] = useState(true)
  useLayoutEffect(() => {
    const element = ref.current
    if (!element) return
    const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize)
    const observer = new ResizeObserver(([entry]) => setIsWide(entry.contentRect.width >= 64 * rem))
    observer.observe(element)
    return () => observer.disconnect()
  }, [ref])
  return isWide
}

/* The shell fills the viewport by default; set block-size on it to put it
   in a smaller box, as the stories do. Breakpoints are the shell's own width
   (a container), which in an app is the viewport's.

   It is a grid with no padding and no gap: it only places the pieces. Its
   background is the Theme's canvas, read through the [data-canvas] switches
   here, against this element's own palette, unless the consumer set
   --canvas (any colour or gradient) through Theme tokens. */
.shell {
  /* What the pieces inside need from the scope around the shell, captured
     here because a piece cannot read its own custom property while
     redefining it. */
  --shell-muted-foreground: var(--muted-foreground);
  --shell-subtle-foreground: var(--subtle-foreground);
  --shell-canvas-foreground: var(--canvas-foreground, var(--foreground));
  /* A solid colour standing for the canvas, for what components draw as
     "the surface under me" (a Badge ring, a Checkbox fill). A gradient
     canvas has none, so the consumer names one with --canvas-solid. */
  --shell-canvas-solid: var(
    --canvas-solid,
    var(--canvas-plain, var(--card)) var(--canvas-neutral, var(--background))
      var(--canvas-tinted, var(--primary-subtle))
  );
  --shell-canvas-subtle-foreground: var(--canvas-muted-foreground, var(--subtle-foreground));
  --shell-canvas-muted-foreground: var(
    --canvas-muted-foreground,
    var(--canvas-plain, var(--muted-foreground)) var(--canvas-neutral, var(--muted-foreground))
      var(--canvas-tinted, var(--subtle-foreground))
  );
  /* A transparent piece on a plain canvas has nothing else marking its edge. */
  --shell-transparent-edge: var(--canvas-plain, var(--border)) var(--canvas-neutral, transparent)
    var(--canvas-tinted, transparent);
  --shell-bar: calc(var(--control-md) + 2 * var(--space-cluster));
  /* The logo lines up with the sidebar's icons: its padding plus an item's. */
  --shell-logo-x: calc(2 * var(--space-inline));

  position: relative;
  container-type: inline-size;
  block-size: 100dvh;
  overflow: hidden;
  background: var(
    --canvas,
    var(--canvas-plain, var(--card)) var(--canvas-neutral, var(--background))
      var(--canvas-tinted, var(--primary-subtle))
  );
  color: var(--foreground);
  font-family: var(--font-sans);
}

.frame {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-columns: minmax(0, 1fr);
  block-size: 100%;
}

/* A solid piece is the card colour and draws the edge it shares with the
   content; a transparent one shows the canvas and reads its text colours. */
/* Scoped to the shell's own cells: a bare attribute selector is not hashed by
   CSS Modules and would match any element in the page. */
:is(.top, .sidebar)[data-surface='solid'] {
  /* stylelint-disable-next-line zweihander/no-token-shadow -- what sits on the piece reads its colour */
  --background: var(--card);
  background: var(--card);
  color: var(--card-foreground);
}
:is(.top, .sidebar)[data-surface='transparent'] {
  /* stylelint-disable zweihander/no-token-shadow -- what sits on the canvas reads the canvas colours */
  --background: var(--shell-canvas-solid);
  --muted-foreground: var(--shell-canvas-muted-foreground);
  --subtle-foreground: var(--shell-canvas-subtle-foreground);
  /* stylelint-enable zweihander/no-token-shadow */
  color: var(--shell-canvas-foreground);
}

.top {
  grid-column: 1 / -1;
  border-block-end: 1px solid var(--border);
}
.top[data-surface='transparent'] {
  border-block-end-color: var(--shell-transparent-edge);
}

.sidebar {
  display: none;
  grid-template-rows: auto minmax(0, 1fr);
  min-block-size: 0;
  /* The Sidebar inside drops its own fill and edge; this cell draws them. */
  --sidebar-background: transparent;
  --sidebar-border: 0;
  border-inline-end: 1px solid var(--border);
}
.sidebar[data-surface='transparent'] {
  border-inline-end-color: var(--shell-transparent-edge);
}
.sidebar > :last-child {
  grid-row: -2;
}
/* In a collapsed rail the logo keeps its place and is cut to the rail's
   width, so a logo should lead with its mark. */
.sidebarBrand {
  display: flex;
  align-items: center;
  block-size: var(--shell-bar);
  padding-inline-start: var(--shell-logo-x);
  overflow: hidden;
}

/* The sidebar from 64rem; below that it lives in the drawer. */
@container (min-width: 64rem) {
  .withSidebar .frame {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .withSidebar .sidebar {
    display: grid;
  }
  /* sidebar layout: the sidebar runs the full height and there is no top bar. */
  .sidebarLayout.withSidebar .top {
    display: none;
  }
  .sidebarLayout.withSidebar .sidebar {
    grid-row: 1 / -1;
  }
}

/* ---------------------------------------------------------------- skip
   Off screen until focused: the first Tab on the page, straight past the
   navigation to the content. */
.skip {
  position: absolute;
  inset-block-start: var(--space-2);
  inset-inline-start: var(--space-2);
  /* Above the sticky header and an open drawer: it is the first thing a
     keyboard user lands on. */
  z-index: var(--layer-tooltip);
  padding: var(--control-sm-pad) var(--control-md-pad-spacious);
  border-radius: var(--radius-field);
  background: var(--primary);
  color: var(--primary-foreground);
  font-size: var(--text-body);
  font-weight: 500;
  text-decoration: none;
  translate: 0 calc(-100% - var(--space-4));
}
.skip:focus-visible {
  translate: 0;
  outline: var(--focus-width) solid var(--ring);
  outline-offset: var(--focus-offset);
}

/* -------------------------------------------------------------- drawer */
.backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--layer-overlay);
  background: var(--scrim);
  transition: opacity var(--duration-base);
}
.backdrop[data-starting-style],
.backdrop[data-ending-style] {
  opacity: 0;
}

.drawer {
  position: fixed;
  inset-block: 0;
  inset-inline-start: 0;
  z-index: var(--layer-overlay);
  display: flex;
  flex-direction: column;
  inline-size: min(20rem, 85vw);
  background: var(--background);
  color: var(--foreground);
  box-shadow: var(--shadow-lg);
  outline: none;
  transition: translate var(--duration-slow);
}
/* The navigation inside (a Sidebar) takes the drawer's width, not its own. */
.drawer > :not(.drawerClose) {
  flex: 1;
  min-block-size: 0;
  inline-size: 100%;
}
.drawer[data-starting-style],
.drawer[data-ending-style] {
  translate: -100% 0;
}
/* [dir] rather than :dir(), which the build lowers to a :lang() list. */
:global([dir='rtl']) .drawer[data-starting-style],
:global([dir='rtl']) .drawer[data-ending-style] {
  translate: 100% 0;
}

.drawerClose {
  position: absolute;
  inset-block-start: var(--space-3);
  inset-inline-end: var(--space-3);
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- local stacking inside the shell, not a global layer */
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--space-8);
  block-size: var(--space-8);
  padding: 0;
  border: 0;
  border-radius: var(--radius-field);
  background: transparent;
  color: var(--muted-foreground);
  font-size: var(--icon-md);
  cursor: var(--cursor-button);
}
.drawerClose:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}
.drawerClose:focus-visible {
  outline: var(--focus-width) solid var(--ring);
  outline-offset: var(--focus-offset);
}

.srOnly {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
